export const DICT = { en, fr };

export const LANGS = [
  { code: "ar", label: "العربية", short: "ع", dir: "rtl" },
  { code: "en", label: "English", short: "EN", dir: "ltr" },
  { code: "fr", label: "Français", short: "FR", dir: "ltr" },
];

const KEY = "teacherhub-lang";
let currentLang = (() => {
  try { return localStorage.getItem(KEY) || "ar"; } catch { return "ar"; }
})();

export function tr(ar, vars) {
  let out = (DICT[currentLang] || {})[ar] ?? ar;
  if (vars) Object.entries(vars).forEach(([k, v]) => { out = out.replaceAll(`{${k}}`, String(v)); });
  return out;
}

const Ctx = createContext({ lang: currentLang, setLang: () => {}, t: tr });


