  "كيف سيراك المفتش لو زارك اليوم؟ درجة محاكاة من 20 محسوبة من أدلة منصتك الحقيقية: خططك، حصصك، نقاطك، متابعتك ووثائقك — مع شبكة ملاحظة حصة محاكاة وخطة تحسين.": "How would the inspector see you if they visited today? A simulated score out of 20 computed from your platform's real evidence: plans, sessions, marks, follow-up and documents — with a simulated observation grid and an improvement plan.",
