export function LangProvider({ children }) {
  const [lang, setLangState] = useState(currentLang);
  const setLang = (code) => {
    const oldDir = (LANGS.find((l) => l.code === lang) || LANGS[1]).dir;
    const next = LANGS.find((l) => l.code === code) || LANGS[1];
    currentLang = code;
    try { localStorage.setItem(KEY, code); } catch { /* ignore */ }
    if (oldDir !== next.dir) {
      // Bootstrap ships separate LTR/RTL builds; reload once so main.jsx loads
      // the stylesheet matching the newly selected direction.
      window.location.reload();
      return;
    }
    setLangState(code);
  };
  useEffect(() => {
    const meta = LANGS.find((l) => l.code === lang) || LANGS[1];
    document.documentElement.lang = lang;
    document.documentElement.dir = meta.dir;
  }, [lang]);
  const t = (ar, vars) => {
    let out = (DICT[lang] || {})[ar] ?? ar;
    if (vars) Object.entries(vars).forEach(([k, v]) => { out = out.replaceAll(`{${k}}`, String(v)); });
    return out;
  };
  return <Ctx.Provider value={{ lang, setLang, t }}>{children}</Ctx.Provider>;
}

