export function trEnum(v) {
  if (v == null) return v;
  return (ENUM_DICT[currentLang] || {})[v] ?? v;
}

export const useLang = () => {
  const ctx = useContext(Ctx);
  const te = (v) => (v == null ? v : (ENUM_DICT[ctx.lang] || {})[v] ?? (DICT[ctx.lang] || {})[v] ?? v);
  return { ...ctx, te };
};

